// Core pure-logic helpers for the Pali VS Code extension.
// These are UI- and VS Code-agnostic so they can be unit-tested without
// the extension host. The activate/deactivate entry points live in
// extension.ts and wire these into the VS Code API.

import * as path from "node:path";
import {
  getReleaseTarget,
  releaseUrl,
  resolvePaliBinary,
  ResolveResult,
  ResolveContext,
  ResolveConfig,
} from "./install_pali";
import { rustLogFilter } from "./logger";
import type { LogLevel } from "./logger";

/** Settings exposed by this extension. */
export interface ExtensionSettings {
  binPath: string;
  repoPath: string;
  remoteUrl: string;
  branch: string;
  scope: string;
  // Directory of an auto-installed embedding model, when one is present.
  modelDir?: string;
  // Explicit model directory from `pali.modelPath`; wins over `modelDir`.
  modelPath?: string;
  // Log level for the extension, the MCP server, and the hooks (default
  // `info`). One knob drives the whole project's verbosity.
  logLevel?: LogLevel;
  // Record git blame commit IDs and line numbers in the scan manifest.
  scanBlame?: boolean;
  // Maximum size of a file included by a repository scan.
  scanMaxFileBytes?: number;
  // Save the insight digest as a memory in the memory repository.
  scanSaveMemories?: boolean;
}

/** One hook command carrying the settings the scripts read from the environment. */
function hookCommand(
  script: string,
  mode: string,
  config: ExtensionSettings,
  shell: "bash" | "powershell",
): string {
  const env: [string, string][] = [
    ["PALI_BIN", config.binPath],
    ["PALI_REPO_PATH", config.repoPath],
    ["PALI_SCOPE", config.scope],
    // The hooks read the same level the extension and server use, so the
    // hook log at ~/.pali-hooks/hook.log stays consistent with the rest.
    ["PALI_HOOK_LOG_LEVEL", config.logLevel],
    // The hook-spawned server embeds recall queries, so it needs the model
    // too; the user's explicit model path wins over the installed copy.
    ["PALI_MODEL_DIR", config.modelPath || config.modelDir],
  ].filter((pair): pair is [string, string] => Boolean(pair[1]));

  // Uninstall and updates delete the extension directory while a hook file
  // written earlier can outlive it. Running node on the missing entry point
  // crashes every event with MODULE_NOT_FOUND, so skip the run quietly and
  // leave the host with a successful, empty hook result.
  if (shell === "bash") {
    const prefix = env.map(([key, value]) => `${key}=${bashQuote(value)}`).join(" ");
    const run = `${prefix ? `${prefix} ` : ""}node ${bashQuote(script)} ${mode}`;
    return `[ -f ${bashQuote(script)} ] || exit 0; ${run}`;
  }
  const prefix = env.map(([key, value]) => `$env:${key}=${powershellQuote(value)};`).join(" ");
  const run = `${prefix ? `${prefix} ` : ""}node ${powershellQuote(script)} ${mode}`;
  return `if (-not (Test-Path -LiteralPath ${powershellQuote(script)})) { exit 0 }; ${run}`;
}

/** Copilot hooks file for the three events this extension wires up. */
export function buildHookConfig(
  extensionPath: string,
  config: ExtensionSettings,
): { version: 1; hooks: Record<string, HookEntry[]> } {
  const script = path.join(extensionPath, "hooks", "copilot-hooks.mjs");
  const entry = (mode: string, timeoutSec: number): HookEntry => ({
    type: "command",
    bash: hookCommand(script, mode, config, "bash"),
    powershell: hookCommand(script, mode, config, "powershell"),
    timeoutSec,
  });
  return {
    version: 1,
    hooks: {
      sessionStart: [entry("session-start", 30)],
      userPromptTransformed: [entry("prompt", 30)],
      agentStop: [entry("stop", 60)],
    },
  };
}

interface HookEntry {
  type: "command";
  bash: string;
  powershell: string;
  timeoutSec: number;
}

/** Stringify the hook config with a trailing newline. */
export function hookConfigBody(extensionPath: string, config: ExtensionSettings): string {
  return `${JSON.stringify(buildHookConfig(extensionPath, config), null, 2)}\n`;
}

/** Stdio server definition for VS Code's MCP server definition provider. */
export interface McpServerDefinition {
  label: string;
  command: string;
  args: string[];
  env: Record<string, string>;
}

export function mcpServerDefinition(
  config: ExtensionSettings,
  token: string | undefined,
): McpServerDefinition {
  const env: Record<string, string> = { PALI_BRANCH: config.branch, NO_COLOR: "1" };
  if (config.repoPath) env.PALI_REPO_PATH = config.repoPath;
  if (config.remoteUrl) env.PALI_REMOTE_URL = config.remoteUrl;
  // The token comes from secret storage, not settings, and only authenticates
  // HTTPS transports. A local path remote never needs one, so it is not passed
  // there — that would widen the token's exposure for no reason.
  if (token && /^https?:\/\//i.test(config.remoteUrl || "")) {
    env.PALI_GIT_TOKEN = token;
  }
  // The server refuses to start without model files. An explicit
  // `pali.modelPath` wins; otherwise point it at the copy the extension
  // installed; without either it falls back to the platform data dir.
  if (config.modelPath) env.PALI_MODEL_DIR = config.modelPath;
  else if (config.modelDir) env.PALI_MODEL_DIR = config.modelDir;
  // The server's tracing filter (RUST_LOG) mirrors the extension's log level
  // so `pali.logLevel` controls both sides of the pipe. The filter is scoped
  // to the `pali` crate so `debug` does not flood the server with dependency
  // noise.
  if (config.logLevel) env.RUST_LOG = rustLogFilter(config.logLevel);

  return {
    label: "Pali Memory",
    command: config.binPath,
    args: ["serve"],
    env,
  };
}

/** Workspace bootstrap subcommands that run against a folder on disk. */
export type WorkspaceBootstrapKind = "scan" | "index" | "scan-repos";

/** A resolved CLI invocation for one workspace bootstrap run. */
export interface WorkspaceBootstrapCommand {
  command: string;
  args: string[];
  env: Record<string, string>;
}

/**
 * Build the `pali scan` / `pali index` invocation for a workspace folder.
 *
 * The CLI writes its artifacts under `<workspace>/.pali` by default. `scan`
 * and `scan-repos` only read text files and never load the model; `index`
 * embeds every chunk, so it receives the same model directory the server
 * uses. `scan-repos` alone can commit the insight digest into the memory
 * repository (`--save-memories`), which is the only path here that writes
 * outside the artifacts directory.
 */
export function workspaceBootstrapCommand(
  kind: WorkspaceBootstrapKind,
  config: ExtensionSettings,
  workspaceRoot: string,
): WorkspaceBootstrapCommand {
  const env: Record<string, string> = { NO_COLOR: "1" };
  if (kind === "index") {
    const modelDir = config.modelPath || config.modelDir;
    if (modelDir) env.PALI_MODEL_DIR = modelDir;
  }
  // Every subcommand logs through tracing, so the configured level applies the
  // same way it does to the server and the hooks.
  if (config.logLevel) env.RUST_LOG = rustLogFilter(config.logLevel);

  const args = [kind, "--workspace", workspaceRoot];
  if (kind === "scan-repos") {
    if (config.scanBlame) args.push("--blame");
    if (config.scanMaxFileBytes) {
      args.push("--max-file-bytes", String(config.scanMaxFileBytes));
    }
    if (config.scanSaveMemories) {
      args.push("--save-memories");
      // The CLI defaults to ~/.memory-mcp and the workspace directory name;
      // only pass values the user actually configured.
      if (config.repoPath) args.push("--repo-path", config.repoPath);
      if (config.scope) args.push("--scope", config.scope);
    }
  }

  return { command: config.binPath, args, env };
}

/**
 * Turn the JSON summary a bootstrap subcommand prints on stdout into the
 * one-line message shown to the user. Unparseable output is passed through so
 * an older binary's plain-text summary is still visible.
 */
export function workspaceBootstrapSummary(
  kind: WorkspaceBootstrapKind,
  stdout: string,
): string {
  const text = stdout.trim();
  let summary: Record<string, unknown>;
  try {
    summary = JSON.parse(text) as Record<string, unknown>;
  } catch {
    return text || `Pali: ${kind} finished without a summary`;
  }
  const count = (key: string): number => Number(summary[key] ?? 0);
  if (kind === "scan-repos") {
    return (
      `Pali: scanned ${count("accepted_files")} files ` +
      `(${count("findings")} findings). Insights: ${summary.insights}`
    );
  }
  if (kind === "scan") {
    return (
      `Pali: scanned ${count("files")} files ` +
      `(${count("sensitive")} sensitive, ${count("findings")} potential secrets). ` +
      `Report: ${summary.report}`
    );
  }
  return (
    `Pali: indexed ${count("chunks")} chunks from ${count("files")} files. ` +
    `Index: ${summary.index}`
  );
}

// Re-export from install_pali for test compatibility
export { getReleaseTarget, releaseUrl, resolvePaliBinary };
export type { ResolveResult, ResolveContext, ResolveConfig };

function bashQuote(value: string): string {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

function powershellQuote(value: string): string {
  return `'${String(value).replace(/'/g, "''")}'`;
}

// UI-agnostic install library for pali binaries.
// Used by install.ts (VS Code wrapper) and testable independently.

import * as fs from "node:fs/promises";
import * as path from "node:path";
import * as zlib from "node:zlib";
import { log } from "./logger";
import modelManifest from "../model-manifest.json";

// Binaries and the embedding model are published by the project's GitHub
// repository. `releases/latest` is GitHub's stable alias for the newest
// release, so a download needs no version lookup. Downloads carry the HTTPS
// token the user stored via `pali.setToken` as a Bearer credential; a private
// repository needs it, a public one ignores it.
const GITHUB_BASE_URL = "https://github.com";
/**
 * REST host. It is not `${GITHUB_BASE_URL}/api/v3` (GitHub Enterprise's
 * path): github.com serves its API from `api.github.com/repos/<owner>/<repo>`,
 * and the `/api/v3` prefix there answers 404, which made every update check
 * come back empty.
 */
const GITHUB_API_URL = "https://api.github.com";
const PROJECT_PATH = "cderivan/memory-mcp";
/** Release download prefix. Asset names are per-target; see releaseAssetName. */
const RELEASE_BASE_URL = `${GITHUB_BASE_URL}/${PROJECT_PATH}/releases`;
/** Project REST root, used only to read the latest release's tag. */
const PROJECT_API_URL = `${GITHUB_API_URL}/repos/${PROJECT_PATH}`;

/**
 * Embedding model layout, read from `model-manifest.json`. The crate embeds the
 * same file (`pali/src/embedding/candle.rs`), so the directory this installer
 * writes to and the directory the server looks in cannot drift apart.
 */
export const MODEL_DIR_NAME = modelManifest.dir;
/** Every file the model loader requires, in manifest order. */
export const MODEL_FILES = [
  modelManifest.files.config,
  modelManifest.files.tokenizer,
  modelManifest.files.weights,
];
/** Project ref that carries the `models/<dir>.zip` archive. */
const MODEL_REF = "main";

// Log lines flow through the shared logger (src/utils/logger.ts): the
// extension host routes them into the "Pali Memory" output channel, and
// standalone runs (tests, scripts) keep the console. The level filter is the
// same `pali.logLevel` setting that drives the server and the hooks.

/** Map host platform/arch to a prebuilt release target, or null if unsupported. */
export function getReleaseTarget(platform: string, arch: string): string | null {
  if (platform === "darwin" && arch === "arm64") return "aarch64-apple-darwin";
  if (platform === "darwin" && arch === "x64") return "x86_64-apple-darwin";
  if (platform === "linux" && arch === "x64") return "x86_64-unknown-linux-gnu";
  if (platform === "win32" && arch === "x64") return "x86_64-pc-windows-msvc";
  return null;
}

/** Return the absolute path to `name` on PATH, or null if not found. */
export function which(name: string): string | null {
  const dirs = (process.env.PATH || "").split(path.delimiter).filter(Boolean);
  const { accessSync } = require("node:fs");
  for (const dir of dirs) {
    const candidate = path.join(dir, name);
    try {
      accessSync(candidate);
      return candidate;
    } catch {
      // not found in this dir
    }
  }
  return null;
}

/**
 * Return true if `file` exists and is executable. Windows carries no exec
 * bits in the file mode, so existence is the whole check there.
 */
export async function isExecutable(file: string): Promise<boolean> {
  try {
    const st = await fs.stat(file);
    if (!st.isFile()) return false;
    if (process.platform === "win32") return true;
    // eslint-disable-next-line no-bitwise
    return (st.mode & 0o111) !== 0;
  } catch {
    return false;
  }
}

/** File name of the pali executable on the current platform. */
export function binaryName(): string {
  return process.platform === "win32" ? "pali.exe" : "pali";
}

/**
 * Return the release asset name for a target. The published assets are not
 * uniform: macOS is a single universal `aarch64-apple-darwin.zip` (used for
 * both arm64 and x64), Windows is `pali.x86_64-pc-windows-msvc.zip`, and
 * Linux x64 is a tarball `x86_64-unknown-linux-gnu.tgz`.
 */
export function releaseAssetName(target: string): string {
  if (target.includes("apple-darwin")) return "aarch64-apple-darwin.zip";
  if (target.includes("windows")) return `pali.${target}.zip`;
  return `${target}.tgz`;
}

/**
 * Build the download URL for a release target. Omitting `version` uses the
 * latest release, which is what the extension installs.
 */
export function releaseUrl(target: string, version?: string): string {
  const ref = version || "latest";
  return `${RELEASE_BASE_URL}/${ref}/download/${releaseAssetName(target)}`;
}

/** Path of the binary staged by `npm run build:binary`. */
export function bundledBinaryPath(extensionPath: string): string {
  return path.join(extensionPath, "out", "bin", binaryName());
}

/**
 * Return the decompressed bytes of the first archive entry that is the pali
 * executable, wherever it sits in the archive (the release may wrap it in a
 * versioned folder). The published archives carry a single executable entry
 * (named `pali`, `pali.exe`, or the bare target triple), so the first regular
 * file is taken. Returns null when none is found.
 */
function readBinaryFromZip(archive: Buffer): Buffer | null {
  let eocd = -1;
  const earliest = Math.max(0, archive.length - 0xffff - 22);
  for (let i = archive.length - 22; i >= earliest; i -= 1) {
    if (archive.readUInt32LE(i) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) return null;

  const entries = archive.readUInt16LE(eocd + 10);
  let offset = archive.readUInt32LE(eocd + 16);
  for (let n = 0; n < entries; n += 1) {
    if (archive.readUInt32LE(offset) !== 0x02014b50) return null;
    const method = archive.readUInt16LE(offset + 10);
    const compressedSize = archive.readUInt32LE(offset + 20);
    const nameLength = archive.readUInt16LE(offset + 28);
    const extraLength = archive.readUInt16LE(offset + 30);
    const commentLength = archive.readUInt16LE(offset + 32);
    const localOffset = archive.readUInt32LE(offset + 42);
    const name = archive.toString("utf8", offset + 46, offset + 46 + nameLength);
    offset += 46 + nameLength + extraLength + commentLength;

    if (name.endsWith("/")) continue;

    if (archive.readUInt32LE(localOffset) !== 0x04034b50) return null;
    const localNameLength = archive.readUInt16LE(localOffset + 26);
    const localExtraLength = archive.readUInt16LE(localOffset + 28);
    const start = localOffset + 30 + localNameLength + localExtraLength;
    const data = archive.subarray(start, start + compressedSize);
    return method === 8 ? zlib.inflateRawSync(data) : Buffer.from(data);
  }
  return null;
}

/**
 * Return the bytes of the first regular file in a (decompressed) tar archive,
 * or null when there is none. The Linux release archive holds a single
 * `pali` executable, so the first regular entry is the binary.
 */
function readBinaryFromTar(tar: Buffer): Buffer | null {
  for (let off = 0; off + 512 <= tar.length; off += 512) {
    const nameEnd = tar.indexOf(0, off, off + 100);
    if (nameEnd < 0) break;
    const name = tar.toString("utf8", off, nameEnd);
    if (!name) break;
    const type = tar[off + 156];
    if (type === 0x30) {
      const size =
        parseInt(
          tar
            .toString("utf8", off + 124, off + 136)
            .replace(/\0.*$/, "")
            .trim(),
          8,
        ) || 0;
      return Buffer.from(tar.subarray(off + 512, off + 512 + size));
    }
    const size =
      parseInt(
        tar
          .toString("utf8", off + 124, off + 136)
          .replace(/\0.*$/, "")
          .trim(),
        8,
      ) || 0;
    off += Math.ceil(size / 512) * 512;
  }
  return null;
}

/**
 * Extract the pali executable out of a release archive into `destDir`, writing
 * it under the current platform's name. macOS and Windows archives are ZIPs;
 * the Linux archive is a gzip-compressed tar.
 */
export async function extractBinaryFromArchive(
  archive: Buffer,
  destDir: string,
  target: string,
): Promise<string> {
  const isTar = target.includes("linux");
  log.info(`reading ${isTar ? "tar.gz" : "zip"} archive (${archive.length} bytes)`);
  const bytes = isTar ? readBinaryFromTar(zlib.gunzipSync(archive)) : readBinaryFromZip(archive);
  if (!bytes) {
    log.error(`archive does not contain a ${binaryName()} executable`);
    throw new Error(`release archive does not contain a ${binaryName()} executable`);
  }
  const dest = path.join(destDir, binaryName());
  await fs.writeFile(dest, bytes);
  // The archive carries no permission bits, so restore the exec bit the
  // server needs to start (a no-op for the read-only bit on Windows).
  await fs.chmod(dest, 0o755);
  log.success(`extracted ${bytes.length} bytes of ${binaryName()}`);
  return dest;
}

/**
 * Read the first bytes of a file, or null when it cannot be read. Used to tell
 * a real binary or model file apart from an HTML login page a failed download
 * left behind.
 */
async function readBinaryHead(file: string, size = 64): Promise<Buffer | null> {
  const fh = await fs.open(file, "r");
  try {
    const head = Buffer.alloc(size);
    const { bytesRead } = await fh.read(head, 0, size, 0);
    return head.subarray(0, bytesRead);
  } finally {
    await fh.close();
  }
}

/** True when the leading bytes look like an HTML document. */
function isHtmlHead(head: Buffer): boolean {
  const text = head.toString("utf8", 0, Math.min(256, head.length));
  return /^\s*<(\!doctype|html)/i.test(text) || /<html[^>]*>/i.test(text);
}

/** Directory holding the model files; `PALI_MODEL_DIR` points the server here. */
export function modelDir(storagePath: string): string {
  return path.join(storagePath, "models", MODEL_DIR_NAME);
}

/**
 * Return the model directory when every required file is present and non-empty,
 * or null when the model still needs to be downloaded.
 */
export async function resolveModelDir(storagePath: string): Promise<string | null> {
  const dir = modelDir(storagePath);
  for (const file of MODEL_FILES) {
    try {
      const st = await fs.stat(path.join(dir, file));
      if (!st.isFile() || st.size === 0) return null;
    } catch {
      return null;
    }
  }
  // A failed download can leave HTML login pages under the model file names;
  // those must not count as an installed model.
  const configHead = await readBinaryHead(path.join(dir, "config.json")).catch(() => null);
  if (configHead && isHtmlHead(configHead)) {
    log.warn(`model at ${dir} is an HTML login page, not a model — ignoring it`);
    return null;
  }
  return dir;
}

/**
 * Explain why a directory cannot serve as `PALI_MODEL_DIR`, or return
 * undefined when every required model file is present. An empty file is not
 * usable either: the server loads the weights at startup, so a truncated
 * install would fail there instead.
 */
export async function modelPathProblem(dir: string): Promise<string | undefined> {
  try {
    const entry = await fs.stat(dir);
    if (!entry.isDirectory()) return `"${dir}" is not a directory`;
  } catch {
    return `"${dir}" does not exist`;
  }

  const missing: string[] = [];
  for (const name of MODEL_FILES) {
    try {
      const st = await fs.stat(path.join(dir, name));
      if (!st.isFile() || st.size === 0) missing.push(name);
    } catch {
      missing.push(name);
    }
  }
  if (missing.length === 0) return undefined;
  return `"${dir}" is missing ${missing.join(", ")}`;
}

/** One Git LFS pointer, as committed instead of the file body. */
export interface LfsPointer {
  oid: string;
  size: number;
}

/**
 * Parse a Git LFS pointer file. Returns null for anything else, including the
 * real file contents, so callers can treat both repository layouts uniformly.
 */
export function parseLfsPointer(text: string): LfsPointer | null {
  if (!text.startsWith("version https://git-lfs")) return null;
  const oid = /^oid sha256:([0-9a-f]{64})$/m.exec(text)?.[1];
  const size = Number(/^size (\d+)$/m.exec(text)?.[1]);
  if (!oid || !Number.isSafeInteger(size)) return null;
  return { oid, size };
}

/**
 * Resolve the pali binary to use. Checks configured binPath (if explicit),
 * then PATH (only for default "pali"), then the globalStorage cache.
 * Returns { path, source } where source is one of
 * 'configured', 'path', 'cache', or 'missing'.
 */
export interface ResolveResult {
  path: string | null;
  source: "bundled" | "configured" | "path" | "cache" | "missing";
}

export interface ResolveContext {
  globalStoragePath: string;
  /** Binary staged by the extension build (`out/bin/pali`), when present. */
  bundledPath?: string;
}

export interface ResolveConfig {
  binPath?: string;
}

export async function resolvePaliBinary(
  context: ResolveContext,
  config: ResolveConfig,
): Promise<ResolveResult> {
  // 0. Binary built and staged with the extension itself.
  if (context.bundledPath && (await isExecutable(context.bundledPath))) {
    log.debug(`bundled binary ${context.bundledPath} is present and executable, using it`);
    return { path: context.bundledPath, source: "bundled" };
  }

  // 1. Explicit binPath (not the default "pali")
  if (config.binPath && config.binPath !== "pali") {
    const resolved = path.isAbsolute(config.binPath)
      ? config.binPath
      : path.resolve(config.binPath);
    if (await isExecutable(resolved)) {
      return { path: resolved, source: "configured" };
    }
    // Fall through: explicit path was not executable
  }

  // 2. Default "pali" - check PATH
  if (!config.binPath || config.binPath === "pali") {
    const pathResult = which("pali");
    if (pathResult) {
      return { path: pathResult, source: "path" };
    }
  }

  // 3. globalStorage cache. The name matches what the installer extracts
  // (binaryName()), so a Windows install lands at `pali.exe` there. A failed
  // download may have left an HTML login page under that name, which must not
  // count as an installed binary — otherwise the re-install offer never shows.
  const cached = path.join(context.globalStoragePath, binaryName());
  if (await isExecutable(cached)) {
    const head = await readBinaryHead(cached).catch(() => null);
    if (head && isHtmlHead(head)) {
      log.warn(`cached binary ${cached} is an HTML login page, not a binary — ignoring it`);
      return { path: null, source: "missing" };
    }
    return { path: cached, source: "cache" };
  }

  // 4. Not found
  return { path: null, source: "missing" };
}

/** Maintenance flags in globalStorage alongside the binary. */
const MAINTENANCE_FILE = "maintenance.json";

interface MaintenanceData {
  installedVersion?: string;
  checkUpdates?: boolean;
}

/** Read maintenance flags from globalStorage. */
async function readMaintenance(storagePath: string): Promise<MaintenanceData> {
  const file = path.join(storagePath, MAINTENANCE_FILE);
  try {
    const content = await fs.readFile(file, "utf8");
    return JSON.parse(content);
  } catch {
    return {};
  }
}

/** Write maintenance flags to globalStorage. Creates the directory if needed. */
async function writeMaintenance(storagePath: string, data: MaintenanceData): Promise<void> {
  await fs.mkdir(storagePath, { recursive: true });
  const file = path.join(storagePath, MAINTENANCE_FILE);
  await fs.writeFile(file, JSON.stringify(data, null, 2), "utf8");
}

/** Bearer credential for private-repo downloads, or no headers when unset. */
function authHeaders(token?: string | null): Record<string, string> {
  const trimmed = token?.trim();
  return trimmed ? { Authorization: `Bearer ${trimmed}` } : {};
}

/** Read the newest release tag from the GitHub Enterprise API. */
async function fetchLatestVersion(token?: string | null): Promise<string | null> {
  try {
    const response = await fetch(`${PROJECT_API_URL}/releases/latest`, {
      headers: authHeaders(token),
    });
    if (!response.ok) return null;
    const release = (await response.json()) as { tag_name?: string };
    return release.tag_name?.trim() || null;
  } catch {
    return null;
  }
}

/** Read the full response body into memory, reporting byte progress. */
async function readBody(
  response: Response,
  onBytes: (received: number, total: number) => void,
): Promise<Buffer> {
  const total = Number(response.headers.get("content-length")) || 0;
  const reader = response.body!.getReader();
  const chunks: Buffer[] = [];
  let received = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    const chunk = Buffer.from(value);
    chunks.push(chunk);
    received += chunk.byteLength;
    if (total > 0) onBytes(received, total);
  }
  return Buffer.concat(chunks);
}

/**
 * Validate the magic bytes of a downloaded archive. A 200 response can still
 * be an SSO login page (GitHub Enterprise redirects unauthenticated requests),
 * so the body must be inspected before it is trusted as a binary or model.
 */
function validateArchiveBytes(bytes: Buffer, dest: string): void {
  const isZip = bytes.length >= 4 && bytes.readUInt32BE(0) === 0x504b0304;
  const isGzip = bytes.length >= 2 && bytes[0] === 0x1f && bytes[1] === 0x8b;
  if (isZip || isGzip) return;
  const head = bytes.toString("utf8", 0, Math.min(256, bytes.length));
  const isHtml = /^\s*<(\!doctype|html)/i.test(head) || /<html[^>]*>/i.test(head);
  if (isHtml) {
    log.error(`download of ${dest} returned an HTML login page, not an archive`);
    throw new Error(
      `The server returned a login page instead of the file for ${dest} ` +
        "(the download was redirected to single sign-on).\n" +
        'Run "Pali: Set HTTPS Token" and store a token with repo read access.',
    );
  }
  log.error(
    `download of ${dest} has unrecognized content ` +
      `(starts ${bytes.subarray(0, 8).toString("hex")})`,
  );
  throw new Error(
    `The downloaded file ${dest} is neither a zip nor a tar.gz archive. ` +
      "The release asset may have moved; check the release page or retry.",
  );
}

/** Bytes of a failed response body kept for the error message. */
const ERROR_SNIPPET_BYTES = 200;

/**
 * Read a short, single-line excerpt of a failed response body, so the error
 * names the page the server actually returned (an SSO interstitial, a
 * permission-denied notice) instead of only its status code. Reads at most
 * ERROR_SNIPPET_BYTES and cancels the stream, so a multi-megabyte error page is
 * never buffered, and never throws: a body that is absent or already consumed
 * just yields the empty string.
 */
async function readErrorSnippet(response: Response): Promise<string> {
  if (!response.body) return "";
  const reader = response.body.getReader();
  try {
    const chunks: Buffer[] = [];
    let size = 0;
    while (size < ERROR_SNIPPET_BYTES) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(Buffer.from(value));
      size += value.byteLength;
    }
    return Buffer.concat(chunks)
      .subarray(0, ERROR_SNIPPET_BYTES)
      .toString("utf8")
      .replace(/<[^>]*>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  } catch {
    return "";
  } finally {
    await reader.cancel().catch(() => {});
  }
}

/** Write a response body to `dest` atomically, reporting byte progress. */
async function streamToFile(
  response: Response,
  dest: string,
  onBytes: (received: number, total: number) => void,
  mode?: number,
): Promise<void> {
  if (!response.ok || !response.body) {
    const base = `Server returned ${response.status} ${response.statusText} for ${response.url}`;
    // A private repo answers 401/403 when no (or a bad) token was supplied.
    const hint =
      response.status === 401 || response.status === 403
        ? '\nRun "Pali: Set HTTPS Token" and store a token with repo read access.'
        : "";
    const snippet = await readErrorSnippet(response);
    const detail = snippet ? `\nServer said: ${snippet}` : "";
    log.error(
      `${response.status} ${response.statusText} for ${response.url}` +
        (snippet ? `: ${snippet}` : ""),
    );
    throw new Error(base + hint + detail);
  }

  const bytes = await readBody(response, onBytes);
  validateArchiveBytes(bytes, dest);
  const tmp = `${dest}.download`;
  await fs.writeFile(tmp, bytes, mode ? { mode } : undefined);
  await fs.rename(tmp, dest);
  log.success(`wrote ${bytes.length} bytes to ${dest}`);
}

/** Download a file with progress reporting. */
async function downloadWithProgress(
  url: string,
  dest: string,
  onProgress: (fraction: number) => void,
  token?: string | null,
): Promise<void> {
  log.info(`downloading ${url}`);
  const tokenPresent = Boolean(authHeaders(token).Authorization);
  log.info(`authenticating with Bearer token: ${tokenPresent ? "yes" : "no"}`);
  const response = await fetch(url, { headers: authHeaders(token) });
  log.info(
    `server answered ${response.status} ${response.statusText} ` +
      `(content-type: ${response.headers.get("content-type") || "unknown"})`,
  );
  await streamToFile(
    response,
    dest,
    (received, total) => {
      onProgress(total > 0 ? received / total : 0);
    },
    0o755,
  );
}

/** Raw URL for the model archive at the tracked ref (GitHub Enterprise). */
function modelZipUrl(): string {
  return `${GITHUB_BASE_URL}/${PROJECT_PATH}/raw/${MODEL_REF}/models/${MODEL_DIR_NAME}.zip`;
}

/**
 * Extract every file entry of a ZIP archive into `destDir` using only
 * `node:zlib` (no external unzip binary). The central directory supplies each
 * entry's compression method and size; the local header locates the data.
 * Handles stored (method 0) and DEFLATE (method 8) entries and rejects any
 * entry that would escape `destDir` (zip-slip).
 */
async function extractZip(archive: Buffer, destDir: string): Promise<void> {
  let eocd = -1;
  const earliest = Math.max(0, archive.length - 0xffff - 22);
  for (let i = archive.length - 22; i >= earliest; i -= 1) {
    if (archive.readUInt32LE(i) === 0x06054b50) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error("model archive is not a valid ZIP");

  const root = path.resolve(destDir);
  const entries = archive.readUInt16LE(eocd + 10);
  let offset = archive.readUInt32LE(eocd + 16);
  for (let n = 0; n < entries; n += 1) {
    if (archive.readUInt32LE(offset) !== 0x02014b50) {
      throw new Error("corrupt ZIP central directory");
    }
    const method = archive.readUInt16LE(offset + 10);
    const compressedSize = archive.readUInt32LE(offset + 20);
    const nameLength = archive.readUInt16LE(offset + 28);
    const extraLength = archive.readUInt16LE(offset + 30);
    const commentLength = archive.readUInt16LE(offset + 32);
    const localOffset = archive.readUInt32LE(offset + 42);
    const name = archive.toString("utf8", offset + 46, offset + 46 + nameLength);
    offset += 46 + nameLength + extraLength + commentLength;

    if (name.endsWith("/")) continue; // directory entry

    const dest = path.resolve(root, name);
    if (dest !== root && !dest.startsWith(root + path.sep)) {
      throw new Error(`model archive entry escapes the model dir: ${name}`);
    }

    if (archive.readUInt32LE(localOffset) !== 0x04034b50) {
      throw new Error(`corrupt ZIP local header for ${name}`);
    }
    const localNameLength = archive.readUInt16LE(localOffset + 26);
    const localExtraLength = archive.readUInt16LE(localOffset + 28);
    const start = localOffset + 30 + localNameLength + localExtraLength;
    const data = archive.subarray(start, start + compressedSize);
    const bytes = method === 8 ? zlib.inflateRawSync(data) : Buffer.from(data);

    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.writeFile(dest, bytes);
  }
}

/** True when the model is already installed under the extension's storage. */
export async function hasModel(storagePath: string): Promise<boolean> {
  return (await resolveModelDir(storagePath)) !== null;
}

/**
 * Download the embedding model into the extension's storage. Returns the model
 * directory on success, or null after reporting the failure — the binary is
 * still usable with a model provisioned elsewhere (`PALI_MODEL_DIR`,
 * `scripts/fetch-model.sh`).
 */
export async function installModel(ui: UI): Promise<string | null> {
  const existing = await resolveModelDir(ui.storagePath);
  if (existing) return existing;

  const dir = modelDir(ui.storagePath);
  const zipPath = path.join(dir, `${MODEL_DIR_NAME}.zip`);
  log.info(`downloading model ${MODEL_DIR_NAME} from ${modelZipUrl()}`);
  try {
    await fs.mkdir(dir, { recursive: true });
    await ui.progress(`Downloading the ${MODEL_DIR_NAME} model...`, null, async (report) => {
      await downloadWithProgress(modelZipUrl(), zipPath, report, await ui.getToken?.());
      // The archive holds the three model files at its root, so extracting
      // it into the model dir lands them exactly where the loader looks.
      await extractZip(await fs.readFile(zipPath), dir);
    });
  } catch (error) {
    log.error(`model download failed: ${(error as Error).message}`);
    ui.error(
      `Could not download the ${MODEL_DIR_NAME} model: ${(error as Error).message}\n` +
        "Run scripts/fetch-model.sh and set PALI_MODEL_DIR instead.",
    );
    return null;
  } finally {
    // Keep only the extracted files, not the archive.
    await fs.rm(zipPath, { force: true }).catch(() => {});
  }
  return dir;
}

/**
 * UI interface that the install library calls back into.
 * install.ts provides a VS Code implementation of this interface.
 */
export interface UI {
  paliPath: string; // get/set; sets paired promise in set paliPath
  storagePath: string; // readonly: globalStorage path
  extensionPath: string; // readonly: extension install path
  /**
   * HTTPS token for private-repo downloads, read from secret storage. Read
   * per download so a token set later via `pali.setToken` applies without a
   * reload. Returns null when none is stored.
   */
  getToken?(): Promise<string | null>;
  error(s: string): void;
  info(s: string): void;
  command(name: string, body: () => any): void;
  choose(prompt: string, options: string[]): Promise<string | undefined>;
  slow<T>(title: string, promise: Promise<T>): Promise<T>;
  progress<T>(
    title: string,
    cancel: AbortController | null,
    body: (progress: (fraction: number) => void) => Promise<T>,
  ): Promise<T>;
  localize(message: string, ...args: Array<string | number | boolean>): string;
  /**
   * Configured `pali.modelPath`, when the user set one. A usable directory
   * suppresses the model download offer: the server starts on it, so asking
   * to download a model would be wrong.
   */
  modelPath?: string;
  /**
   * Called after an install finishes, so the host can re-resolve the server
   * inputs and restart it: an install is the moment a server that had nothing
   * to start with becomes startable, without waiting for the next activation.
   */
  installed?(): void;
  shouldReuse(release: string): Promise<boolean | undefined>;
  promptReload(message: string): Promise<void>;
  showHelp(message: string, url: string): Promise<void>;
  promptUpdate(oldVersion: string, newVersion: string): Promise<void>;
  promptInstall(version: string): Promise<void>;
}

/**
 * Prepare the pali binary: resolve it, auto-install if missing (when
 * checkUpdates is true and binary is missing), and return the resolved path.
 */
/** Outcome of resolving everything the server needs to start. */
export interface PrepareResult {
  paliPath: string | null;
  modelDir: string | null;
  source: ResolveResult["source"];
}

/**
 * Return the model directory, offering a download when `offer` is set and the
 * model is not installed yet. Choosing "Later" (or dismissing the prompt)
 * leaves the model uninstalled for this session.
 */
/**
 * The configured `pali.modelPath` when it holds every model file, else null.
 * An unusable path must not suppress the download offer: the server cannot
 * start on it, and the extension reports that problem separately.
 */
async function usableConfiguredModel(ui: UI): Promise<string | null> {
  const configured = ui.modelPath?.trim();
  if (!configured) return null;
  return (await modelPathProblem(configured)) === undefined ? configured : null;
}

async function provisionModel(ui: UI, offer: boolean): Promise<string | null> {
  const configured = await usableConfiguredModel(ui);
  if (configured) return configured;
  const installed = await resolveModelDir(ui.storagePath);
  if (installed || !offer) return installed;

  const download = await ui.choose(
    `The ${MODEL_DIR_NAME} embedding model (about 130 MB) is not installed. Download it now?`,
    ["Download now", "Later"],
  );
  if (download !== "Download now") return null;
  const downloaded = await installModel(ui);
  if (downloaded) ui.installed?.();
  return downloaded;
}

/**
 * Offer to download the pali binary when it is missing. Choosing "Later" (or
 * dismissing the prompt) leaves the server uninstalled for this session.
 */
async function provisionBinary(ui: UI): Promise<boolean> {
  const download = await ui.choose("The pali binary was not found. Download and install it now?", [
    "Download now",
    "Later",
  ]);
  return download === "Download now";
}

export async function prepare(ui: UI, autoCheck: boolean): Promise<PrepareResult> {
  const resolve = () =>
    resolvePaliBinary(
      {
        globalStoragePath: ui.storagePath,
        bundledPath: bundledBinaryPath(ui.extensionPath),
      },
      { binPath: ui.paliPath },
    );

  let resolved = await resolve();
  log.info(`resolved pali binary from ${resolved.source} (${resolved.path ?? "not found"})`);

  // The missing-binary offer is unconditional. `checkUpdates` governs update
  // prompts for an installed binary; gating first-install on it rebinds the
  // prompt to the wrong question, and leaves an installation that can never
  // start once update checks are off.
  let modelOffered = false;
  if (resolved.source === "missing") {
    if (await provisionBinary(ui)) {
      let installed = false;
      try {
        // installLatest asks for the model in the same flow.
        await installLatest(ui);
        installed = true;
      } catch (error) {
        ui.error(`Could not install pali: ${(error as Error).message}`);
      }
      modelOffered = installed;
      resolved = await resolve();
    }
    if (resolved.source === "missing") {
      // Nothing can start without the binary, so the model prompt would only
      // be noise: the server would still be unstartable.
      return { paliPath: null, modelDir: null, source: resolved.source };
    }
  }

  // A bundled binary is versioned with the extension, so the release channel
  // and its update prompts do not apply. The model is still needed, and so is
  // it when the binary was found on PATH or in the cache.
  const modelDir = modelOffered
    ? ((await usableConfiguredModel(ui)) ?? (await resolveModelDir(ui.storagePath)))
    : await provisionModel(ui, true);

  if (resolved.source === "bundled") {
    return { paliPath: resolved.path, modelDir, source: resolved.source };
  }

  // If found on PATH, cache the absolute path so we do not re-search.
  if (resolved.source === "path" && resolved.path) {
    ui.paliPath = resolved.path;
  }

  // Check for updates if enabled
  if (autoCheck) {
    await checkUpdates(false, ui);
  }

  return {
    paliPath: resolved.path,
    modelDir,
    source: resolved.source,
  };
}

/**
 * Download and install the latest pali release for the current platform,
 * together with the embedding model the server needs at startup.
 * Throws if platform is unsupported or download fails.
 */
export async function installLatest(ui: UI): Promise<void> {
  const target = getReleaseTarget(process.platform, process.arch);
  if (!target) {
    log.error(`no prebuilt binary for ${process.platform}-${process.arch}`);
    throw new Error(
      `Prebuilt binaries are not available for ${process.platform}-${process.arch}. ` +
        `Set "pali.path" to a manually built pali, or download from the release page.`,
    );
  }
  log.info(`installing pali for ${process.platform}-${process.arch} (target ${target})`);

  // Only prompt about reuse if a cached binary is actually on disk.
  const existingPath = path.join(ui.storagePath, binaryName());
  const maintenance = await readMaintenance(ui.storagePath);
  const installedVersion = maintenance.installedVersion;
  if (installedVersion && (await isExecutable(existingPath))) {
    const shouldReuse = await ui.shouldReuse(installedVersion);
    if (shouldReuse === false) {
      try {
        await fs.unlink(existingPath);
      } catch {
        // ignore
      }
    } else if (shouldReuse === true) {
      ui.info(`pali ${installedVersion} is already installed.`);
      return;
    }
    // If undefined (dismissed), fall through and reinstall
  }

  // Ensure the storage directory exists before writing the binary.
  await fs.mkdir(ui.storagePath, { recursive: true });

  await ui.progress(`Installing pali (${target})...`, null, async (reportProgress) => {
    const url = releaseUrl(target);
    const archivePath = path.join(ui.storagePath, releaseAssetName(target));
    const dest = path.join(ui.storagePath, binaryName());
    log.info(`release asset: ${releaseAssetName(target)} from ${url}`);
    try {
      await downloadWithProgress(url, archivePath, reportProgress, await ui.getToken?.());
      log.info(`extracting ${binaryName()} from ${path.basename(archivePath)}...`);
      await extractBinaryFromArchive(await fs.readFile(archivePath), ui.storagePath, target);
      log.success(`binary extracted to ${dest}`);
      ui.paliPath = dest;
    } finally {
      // Keep only the extracted executable, not the archive.
      await fs.rm(archivePath, { force: true }).catch(() => {});
    }

    // Try to get the version from the binary. `pali --version` prints
    // "pali <semver>"; keep only the version so update checks compare tags.
    let version = "latest";
    try {
      const { execFile } = require("node:child_process");
      const { promisify } = require("node:util");
      const execFileAsync = promisify(execFile);
      const { stdout } = await execFileAsync(dest, ["--version"]);
      version = stdout.trim().split(/\s+/).pop() || "latest";
    } catch {
      // Keep 'latest' if version check fails
    }

    await writeMaintenance(ui.storagePath, {
      installedVersion: version,
      checkUpdates: true,
    });
  });

  // The server cannot start without the embedding model, so offer it in the
  // same install flow. The prompt keeps the ~130 MB download a user choice;
  // installModel reports its own failure, so a model problem never blocks the
  // binary install.
  await provisionModel(ui, true);

  await ui.promptReload(`pali installed at ${ui.paliPath}`);
}

/** Normalise a release tag for comparison ("v1.0.0" and "1.0.0" are equal). */
function normalizeVersion(version: string): string {
  return version.trim().replace(/^v/i, "");
}

/**
 * Check for updates. If force is true, always check even if the user
 * previously dismissed. If force is false, respect the checkUpdates setting.
 */
export async function checkUpdates(force: boolean, ui: UI): Promise<void> {
  const maintenance = await readMaintenance(ui.storagePath);
  if (!force && maintenance.checkUpdates === false) {
    return; // user previously dismissed
  }

  const target = getReleaseTarget(process.platform, process.arch);
  if (!target) return;

  const latestVersion = await fetchLatestVersion(await ui.getToken?.());
  if (!latestVersion) return;

  const installedVersion = maintenance.installedVersion;
  if (!installedVersion || normalizeVersion(installedVersion) !== normalizeVersion(latestVersion)) {
    await ui.promptUpdate(installedVersion || "unknown", latestVersion);
  }
}

// Level-filtering logger shared by the extension host and the install
// library. Every Pali log line produced by the extension flows through here,
// so the "Pali Memory" output channel carries one consistent, level-filtered
// stream instead of scattered `console.log` calls that are invisible outside
// the extension host.
//
// The same `pali.logLevel` setting also drives the MCP server (`RUST_LOG`)
// and the Copilot hooks (`PALI_HOOK_LOG_LEVEL`), so one knob controls the
// whole project's verbosity.

export type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'off';

const WEIGHT: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
  off: 100,
};

/** Map a raw setting value to a known level; unknown values fall back to `info`. */
export function normalizeLogLevel(value: unknown): LogLevel {
  const raw = String(value ?? '').trim().toLowerCase();
  return raw in WEIGHT ? (raw as LogLevel) : 'info';
}

/**
 * The `RUST_LOG` filter for the MCP server at a given level. The filter is
 * scoped to the `pali` crate so `debug` does not flood the server with
 * dependency noise (git2, tokio, ...); everything else stays at its default.
 * `info` reproduces the server's built-in default exactly.
 */
export function rustLogFilter(level: LogLevel): string {
  switch (level) {
    case 'debug':
      return 'pali=debug,info';
    case 'info':
      return 'pali=info,warn';
    case 'warn':
      return 'pali=warn';
    case 'error':
      return 'pali=error';
    case 'off':
      return 'off';
  }
}

export type LogSink = (line: string) => void;

class Logger {
  private level: LogLevel = 'info';
  // The extension host replaces this with the output channel; standalone
  // runs (tests, scripts) keep the console.
  private sink: LogSink = (line) => console.log(line);

  setLevel(level: LogLevel): void {
    this.level = level;
  }

  /** Replace the sink, returning the previous one so callers can restore it. */
  setSink(sink: LogSink): LogSink {
    const previous = this.sink;
    this.sink = sink;
    return previous;
  }

  private emit(level: LogLevel, message: string): void {
    if (WEIGHT[level] < WEIGHT[this.level]) return;
    this.sink(
      `[${new Date().toISOString()}] ${level.toUpperCase().padEnd(5)} [pali] ${message}`,
    );
  }

  debug(message: string): void {
    this.emit('debug', message);
  }

  info(message: string): void {
    this.emit('info', message);
  }

  /** Install-flow success marker; logged at `info`. */
  success(message: string): void {
    this.emit('info', message);
  }

  warn(message: string): void {
    this.emit('warn', message);
  }

  error(message: string): void {
    this.emit('error', message);
  }
}

export const log = new Logger();

// Pali Memory VS Code Extension
// Registers the Pali memory MCP server and installs its GitHub Copilot hooks.

import { spawn } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import * as vscode from 'vscode';
import { activate as installActivate } from './utils/install';
import {
  bundledBinaryPath,
  MODEL_FILES,
  modelPathProblem,
  resolveModelDir,
  resolvePaliBinary,
} from './utils/install_pali';
import type { ResolveResult } from './utils/install_pali';
import {
  hookConfigBody,
  mcpServerDefinition,
  workspaceBootstrapCommand,
  workspaceBootstrapSummary,
  ExtensionSettings,
} from './utils/lib';
import type {
  WorkspaceBootstrapCommand,
  WorkspaceBootstrapKind,
} from './utils/lib';
import { log, normalizeLogLevel } from './utils/logger';

const CONFIG_SECTION = 'pali';
const MCP_PROVIDER_ID = 'pali';
const TOKEN_KEY = 'gitToken';

/**
 * Resolve the binary that would actually run: the copy staged by
 * `npm run build:binary`, a configured path, PATH, or the auto-installed
 * cache. `path` is null when none of them exists.
 */
async function resolveBinary(
  context: vscode.ExtensionContext,
): Promise<ResolveResult> {
  const config = vscode.workspace.getConfiguration(CONFIG_SECTION);
  const configured = String(config.get('path') || 'pali').trim() || 'pali';
  return resolvePaliBinary(
    {
      globalStoragePath: context.globalStorageUri.fsPath,
      bundledPath: bundledBinaryPath(context.extensionPath),
    },
    { binPath: configured },
  );
}

/**
 * The last unusable `pali.modelPath` reported, so the provider and every hook
 * rewrite do not repeat the same notification.
 */
let reportedModelPath: string | undefined;

/**
 * Accept `pali.modelPath` only when the directory holds the model files the
 * server loads. A bad value is reported once and withheld from the server and
 * the hooks: passing it on would only surface later as an opaque startup
 * failure, and the server can still start on the installed model.
 */
async function usableModelPath(configured: string): Promise<string | undefined> {
  if (!configured) {
    reportedModelPath = undefined;
    return undefined;
  }
  const problem = await modelPathProblem(configured);
  if (!problem) {
    reportedModelPath = undefined;
    return configured;
  }
  if (reportedModelPath !== configured) {
    reportedModelPath = configured;
    const message =
      `Pali: pali.modelPath is not usable — ${problem}. ` +
      `The server needs ${MODEL_FILES.join(', ')}. ` +
      'Fix the setting, or clear it to use the installed model.';
    log.error(message);
    void vscode.window.showErrorMessage(message);
  }
  return undefined;
}

/**
 * Read settings for the hooks and the server definition. The installed model
 * directory travels with the same binary resolution.
 */
async function settings(
  context: vscode.ExtensionContext,
  resolved?: ResolveResult,
): Promise<ExtensionSettings> {
  const config = vscode.workspace.getConfiguration(CONFIG_SECTION);
  const configured = String(config.get('path') || 'pali').trim() || 'pali';
  const binary = resolved ?? (await resolveBinary(context));
  const modelDir = await resolveModelDir(context.globalStorageUri.fsPath);
  return {
    binPath: binary.path ?? configured,
    repoPath: String(config.get('repoPath') || '').trim(),
    remoteUrl: String(config.get('remoteUrl') || '').trim(),
    branch: String(config.get('branch') || 'main').trim() || 'main',
    scope: String(config.get('scope') || '').trim(),
    modelDir: modelDir ?? undefined,
    modelPath: await usableModelPath(String(config.get('modelPath') || '').trim()),
    logLevel: normalizeLogLevel(config.get('logLevel')),
    scanBlame: Boolean(config.get('scanBlame')),
    scanMaxFileBytes: Number(config.get('scanMaxFileBytes')) || undefined,
    scanSaveMemories: config.get<boolean>('scanSaveMemories') ?? true,
  };
}

/**
 * The user-level Copilot hooks file. VS Code reads `<home>/.copilot/hooks/*.json`
 * for every workspace, so one install covers every project instead of leaving
 * a `.github/hooks/pali.json` copy behind in each one. `pali.scope` (or the
 * hook's own git-repo derivation) still keeps memories per project.
 *
 * `PALI_HOOKS_DIR` overrides the directory so tests never write the real one.
 */
function hookConfigPath(): string {
  const dir =
    process.env.PALI_HOOKS_DIR || path.join(os.homedir(), '.copilot', 'hooks');
  return path.join(dir, 'pali.json');
}

/** Write the user-level hooks file, leaving it untouched when it is current. */
async function installHooks(
  context: vscode.ExtensionContext,
  quiet: boolean,
): Promise<boolean> {
  const target = hookConfigPath();
  const body = hookConfigBody(context.extensionPath, await settings(context));
  let current = '';
  try {
    current = fs.readFileSync(target, 'utf8');
  } catch {
    // Missing file: write it below.
  }
  if (current === body) return true;

  try {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, body, 'utf8');
  } catch (error) {
    if (!quiet) {
      vscode.window.showWarningMessage(
        `Pali: could not write the hook config: ${(error as Error).message}`,
      );
    }
    return false;
  }
  return true;
}

/**
 * Re-resolve the binary and model, then ask VS Code to re-read the server
 * definition. Installs end here so a server that had nothing to start with
 * comes up without a window reload.
 */
async function refreshServer(
  context: vscode.ExtensionContext,
  serverChanged: vscode.EventEmitter<void>,
  output: vscode.OutputChannel,
): Promise<void> {
  const resolved = await resolveBinary(context);
  if (!resolved.path) {
    output.appendLine('pali: binary still not found; MCP server not started');
  } else {
    const modelDir = await resolveModelDir(context.globalStorageUri.fsPath);
    output.appendLine(
      `pali: using binary at ${resolved.path} (${resolved.source})` +
        (modelDir ? ` (model: ${modelDir})` : ' (no installed model)'),
    );
  }
  serverChanged.fire();
}

/**
 * Update the pali.path setting to point to the installed binary and fire
 * the server change event so VS Code re-requests the MCP definition.
 */
async function updateBinPathSetting(
  newPath: string,
  serverChanged: vscode.EventEmitter<void>,
  output: vscode.OutputChannel,
): Promise<void> {
  const config = vscode.workspace.getConfiguration(CONFIG_SECTION);
  await config.update('path', newPath, vscode.ConfigurationTarget.Global);
  output.appendLine(`pali: path updated to ${newPath}`);
  serverChanged.fire();
}

/** One `pali scan` / `pali index` run, from spawn to exit. */
interface BootstrapOutcome {
  code: number | null;
  stdout: string;
  cancelled: boolean;
}

/**
 * Run a bootstrap subcommand, mirroring its stderr (the CLI's tracing output)
 * into the output channel. Cancelling the progress notification kills the
 * child, so a long `index` run does not have to finish to be abandoned.
 */
function runBootstrap(
  invocation: WorkspaceBootstrapCommand,
  output: vscode.OutputChannel,
  cancellation: vscode.CancellationToken,
): Promise<BootstrapOutcome> {
  return new Promise((resolve, reject) => {
    const child = spawn(invocation.command, invocation.args, {
      env: { ...process.env, ...invocation.env },
      windowsHide: true,
    });
    let stdout = '';
    let cancelled = false;
    const subscription = cancellation.onCancellationRequested(() => {
      cancelled = true;
      child.kill();
    });

    child.stdout.on('data', (chunk: Buffer) => {
      stdout += chunk.toString();
    });
    child.stderr.on('data', (chunk: Buffer) => {
      output.append(chunk.toString());
    });
    child.on('error', (error) => {
      subscription.dispose();
      reject(error);
    });
    child.on('close', (code) => {
      subscription.dispose();
      resolve({ code, stdout, cancelled });
    });
  });
}

/**
 * Run `pali scan` or `pali index` against the first workspace folder. The
 * subcommands read the folder and write only under its `.pali/` artifacts
 * directory, so this never touches the memory repository.
 */
async function bootstrapWorkspace(
  kind: WorkspaceBootstrapKind,
  context: vscode.ExtensionContext,
  output: vscode.OutputChannel,
): Promise<void> {
  const labels: Record<WorkspaceBootstrapKind, string> = {
    scan: 'Scan workspace',
    index: 'Index workspace',
    'scan-repos': 'Scan repositories',
  };
  const label = labels[kind];
  const folder = vscode.workspace.workspaceFolders?.[0];
  if (!folder) {
    void vscode.window.showErrorMessage(
      `Pali: open a folder before running "Pali: ${label}".`,
    );
    return;
  }

  const resolved = await resolveBinary(context);
  if (!resolved.path) {
    void vscode.window.showErrorMessage(
      'Pali: the pali binary was not found. Run "Pali: Install pali" first.',
    );
    return;
  }

  const invocation = workspaceBootstrapCommand(
    kind,
    await settings(context, resolved),
    folder.uri.fsPath,
  );
  output.show(true);
  output.appendLine(
    `pali ${kind}: ${invocation.command} ${invocation.args.join(' ')}`,
  );

  let outcome: BootstrapOutcome;
  try {
    outcome = await vscode.window.withProgress(
      {
        location: vscode.ProgressLocation.Notification,
        title: `Pali: ${label.toLowerCase()} ${path.basename(folder.uri.fsPath)}`,
        cancellable: true,
      },
      (_, cancellation) => runBootstrap(invocation, output, cancellation),
    );
  } catch (error) {
    const message = `Pali: could not run "${invocation.command}": ${(error as Error).message}`;
    output.appendLine(message);
    void vscode.window.showErrorMessage(message);
    return;
  }

  if (outcome.cancelled) {
    output.appendLine(`pali ${kind}: cancelled`);
    return;
  }
  if (outcome.code !== 0) {
    const message =
      `Pali: ${kind} failed (exit ${outcome.code ?? 'signal'}). ` +
      'See the "Pali Memory" output for details.';
    output.appendLine(message);
    void vscode.window.showErrorMessage(message);
    return;
  }

  const message = workspaceBootstrapSummary(kind, outcome.stdout);
  output.appendLine(message);
  void vscode.window.showInformationMessage(message);
}

function activate(context: vscode.ExtensionContext): void {
  // Event emitter to signal VS Code to re-request the MCP server definition
  const serverChanged = new vscode.EventEmitter<void>();
  const output = vscode.window.createOutputChannel('Pali Memory');
  context.subscriptions.push(serverChanged, output);

  // Route every extension- and install-side log line through the shared
  // logger into the output channel, at the level the user configured. The
  // same level is passed to the MCP server (RUST_LOG) and the hooks
  // (PALI_HOOK_LOG_LEVEL) via the settings below, so one knob controls the
  // whole project's verbosity.
  log.setSink((line) => output.appendLine(line));
  log.setLevel(normalizeLogLevel(
    vscode.workspace.getConfiguration(CONFIG_SECTION).get('logLevel'),
  ));

  // The token lives in secret storage (the OS keychain), not in settings.json,
  // so it never lands in a workspace file that can be committed or synced.
  const setToken = async (): Promise<void> => {
    const entered = await vscode.window.showInputBox({
      title: 'Pali: HTTPS personal access token',
      prompt:
        'Stored in VS Code\'s secret storage, never in settings.json. Leave empty to clear.',
      password: true,
      ignoreFocusOut: true,
      placeHolder: 'ghp_…',
    });
    if (entered === undefined) return; // cancelled

    const token = entered.trim();
    if (!token) {
      await context.secrets.delete(TOKEN_KEY);
      output.appendLine('cleared HTTPS token');
    } else {
      await context.secrets.store(TOKEN_KEY, token);
      output.appendLine('stored HTTPS token in secret storage');
    }
    serverChanged.fire();
  };

  const clearToken = async (): Promise<void> => {
    await context.secrets.delete(TOKEN_KEY);
    output.appendLine('cleared HTTPS token');
    serverChanged.fire();
  };

  context.subscriptions.push(
    // Prompted installs and hook rewrites end by asking for a restart; firing
    // the change event makes VS Code re-request the server definition.
    vscode.commands.registerCommand('pali.restart', () =>
      void refreshServer(context, serverChanged, output)),
    vscode.commands.registerCommand('pali.setToken', setToken),
    vscode.commands.registerCommand('pali.clearToken', clearToken),
    vscode.commands.registerCommand('pali.scan', () =>
      bootstrapWorkspace('scan', context, output)),
    vscode.commands.registerCommand('pali.index', () =>
      bootstrapWorkspace('index', context, output)),
    vscode.commands.registerCommand('pali.scanRepositories', () =>
      bootstrapWorkspace('scan-repos', context, output)),
    vscode.lm?.registerMcpServerDefinitionProvider?.(MCP_PROVIDER_ID, {
      onDidChangeMcpServerDefinitions: serverChanged.event,
      provideMcpServerDefinitions: async (): Promise<vscode.McpServerDefinition[]> => {
        // Resolve before answering. A definition whose command does not exist
        // only produces a spawn ENOENT when VS Code starts it, so with no
        // binary there is no server to offer: activation has prompted to
        // install one, and `Pali: Install pali` can be run explicitly.
        const resolved = await resolveBinary(context);
        if (!resolved.path) {
          output.appendLine(
            'MCP server not started: the pali binary was not found. ' +
              'Run "Pali: Install pali", then restart the server.',
          );
          return [];
        }
        const token = await context.secrets.get(TOKEN_KEY);
        // Resolution carries the staged binary and the installed model, so
        // the server definition never falls back to defaults that miss them.
        const definition = mcpServerDefinition(
          await settings(context, resolved),
          token,
        );
        output.appendLine(
          `MCP server definition: ${definition.command} ${definition.args.join(' ')}` +
            (definition.env.PALI_GIT_TOKEN ? ' (HTTPS token configured)' : '') +
            (definition.env.PALI_MODEL_DIR ? ` (model: ${definition.env.PALI_MODEL_DIR})` : ''),
        );
        return [
          new vscode.McpStdioServerDefinition(
            definition.label,
            definition.command,
            definition.args,
            definition.env,
          ),
        ];
      },
    }),
    vscode.workspace.onDidChangeConfiguration((event) => {
      if (!event.affectsConfiguration(CONFIG_SECTION)) return;
      if (event.affectsConfiguration(`${CONFIG_SECTION}.logLevel`)) {
        log.setLevel(normalizeLogLevel(
          vscode.workspace.getConfiguration(CONFIG_SECTION).get('logLevel'),
        ));
      }
      void installHooks(context, true);
      serverChanged.fire();
    }),
  );

  output.appendLine(
    typeof vscode.lm?.registerMcpServerDefinitionProvider === 'function'
      ? `registered MCP server definition provider "${MCP_PROVIDER_ID}"`
      : 'this VS Code build has no MCP server definition provider API; update VS Code 1.101 or newer',
  );

  // Install the Copilot hooks
  void installHooks(context, true);

  // Initialize the pali binary: resolve existing or offer to install. The
  // token getter reads secret storage per download so a token set via
  // `pali.setToken` unlocks the private-repo binary and model downloads.
  installActivate(
    context.subscriptions,
    context.globalStorageUri.fsPath,
    context.extensionPath,
    () => void refreshServer(context, serverChanged, output),
    async () => (await context.secrets.get(TOKEN_KEY)) ?? null,
  )
    .then((status) => {
      if (!status.paliPath) {
        output.appendLine('pali: binary not found; awaiting user action');
        return;
      }
      output.appendLine(`pali: using binary at ${status.paliPath} (${status.source})`);
      // A bundled binary lives in the extension's own directory and changes
      // with the extension version, so it is re-resolved on every activation
      // instead of being written into settings.
      if (status.source !== 'bundled') {
        updateBinPathSetting(status.paliPath, serverChanged, output);
      }
    })
    .catch((error) => {
      output.appendLine(`pali: binary resolution failed: ${error.message}`);
    });

  // The install.ts handles auto-check and registration of pali.install/pali.update/pali.restart
}

function deactivate(): void {}

export { activate, deactivate };

// Automatically install pali binary releases from GitHub.
// This wraps `@pali/install` in the VSCode UI. See that package for more.

import * as common from './install_pali';
import * as path from 'path';
import * as vscode from 'vscode';

import * as config from './config';

// Returns the pali path to be used, or null if pali is not installed.
export async function activate(disposables: vscode.Disposable[],
                               globalStoragePath: string,
                               extensionPath: string,
                               onInstalled?: () => void,
                               getToken?: () => Promise<string | null>):
    Promise<common.PrepareResult> {
  const ui = await UI.create(disposables, globalStoragePath, extensionPath,
                             onInstalled, getToken);
  disposables.push(vscode.commands.registerCommand(
      'pali.install', async () => common.installLatest(ui)));
  disposables.push(vscode.commands.registerCommand(
      'pali.update', async () => common.checkUpdates(true, ui)));
  // The installer cannot read VS Code settings itself. Passing the configured
  // model path lets prepare() and installLatest() skip the download offer for
  // a model the user already provisioned.
  ui.modelPath = String((await config.get<string>('modelPath')) || '').trim();
  return await common.prepare(ui, await config.get<boolean>('checkUpdates'));
}

class UI {
  static async create(disposables: vscode.Disposable[],
                      globalStoragePath: string,
                      extensionRoot: string,
                      onInstalled?: () => void,
                      tokenGetter?: () => Promise<string | null>): Promise<UI> {
    const ui = new UI(disposables, globalStoragePath, extensionRoot, tokenGetter);
    ui.installed = onInstalled;
    await ui.resolvePaliPath();
    return ui;
  }

  private constructor(private disposables: vscode.Disposable[],
                      private globalStoragePath: string,
                      private extensionRoot: string,
                      private tokenGetter?: () => Promise<string | null>) {}

  /** Set by activate(): re-resolves and restarts the server after an install. */
  installed?: () => void;
  /** Configured `pali.modelPath`; a usable one suppresses the model offer. */
  modelPath?: string;

  get storagePath(): string { return this.globalStoragePath; }
  get extensionPath(): string { return this.extensionRoot; }
  /** HTTPS token for private-repo downloads, read fresh from secret storage. */
  async getToken(): Promise<string | null> {
    return (await this.tokenGetter?.()) ?? null;
  }
  async choose(prompt: string, options: string[]): Promise<string|undefined> {
    return await vscode.window.showInformationMessage(prompt, ...options);
  }
  slow<T>(title: string, result: Promise<T>) {
    const opts = {
      location: vscode.ProgressLocation.Notification,
      title: title,
      cancellable: false,
    };
    return Promise.resolve(vscode.window.withProgress(opts, () => result));
  }
  progress<T>(title: string, cancel: AbortController|null,
              body: (progress: (fraction: number) => void) => Promise<T>) {
    const opts = {
      location: vscode.ProgressLocation.Notification,
      title: title,
      cancellable: cancel !== null,
    };
    const result = vscode.window.withProgress(opts, async (progress, canc) => {
      if (cancel)
        canc.onCancellationRequested(() => cancel.abort());
      let lastFraction = 0;
      return body(fraction => {
        if (fraction > lastFraction) {
          progress.report({increment: 100 * (fraction - lastFraction)});
          lastFraction = fraction;
        }
      });
    });
    return Promise.resolve(result); // Thenable to real promise.
  }
  localize(message: string, ...args: Array<string|number|boolean>): string {
    let ret = message;
    for (const i in args) {
      ret = ret.replace(`{${i}}`, args[i].toString());
    }
    return ret;
  }
  error(s: string) { vscode.window.showErrorMessage(s); }
  info(s: string) { vscode.window.showInformationMessage(s); }
  command(name: string, body: () => any) {
    this.disposables.push(vscode.commands.registerCommand(name, body));
  }

  async shouldReuse(release: string): Promise<boolean|undefined> {
    const message = `pali ${release} is already installed!`;
    const use = 'Use the installed version';
    const reinstall = 'Delete it and reinstall';
    const response =
        await vscode.window.showInformationMessage(message, use, reinstall);
    if (response === use) {
      // Find pali within the existing directory.
      return true;
    } else if (response === reinstall) {
      // Remove the existing installation.
      return false;
    } else {
      // User dismissed prompt, bail out.
      return undefined;
    }
  }

  private _pathUpdated: Promise<void>|null = null;

  async promptReload(message: string) {
    vscode.window.showInformationMessage(message);
    await this._pathUpdated;
    this._pathUpdated = null;
    vscode.commands.executeCommand('pali.restart');
  }

  async showHelp(message: string, url: string) {
    if (await vscode.window.showInformationMessage(message, 'Open website'))
      vscode.env.openExternal(vscode.Uri.parse(url));
  }

  async promptUpdate(oldVersion: string, newVersion: string) {
    const message = 'An updated pali language server is available.\n ' +
                    `Would you like to upgrade to pali ${newVersion}? ` +
                    `(from ${oldVersion})`;
    const update = `Install pali ${newVersion}`;
    const dontCheck = 'Don\'t ask again';
    const response =
        await vscode.window.showInformationMessage(message, update, dontCheck);
    if (response === update) {
      common.installLatest(this);
    } else if (response === dontCheck) {
      config.update('checkUpdates', false, vscode.ConfigurationTarget.Global);
    }
  }

  async promptInstall(version: string) {
    const p = this.paliPath;
    let message = '';
    if (p.indexOf(path.sep) < 0) {
      message += `The '${p}' language server was not found on your PATH.\n`;
    } else {
      message += `The pali binary '${p}' was not found.\n`;
    }
    message += `Would you like to download and install pali ${version}?`;
    if (await vscode.window.showInformationMessage(message, 'Install'))
      common.installLatest(this);
  }

  async resolvePaliPath() {
    let p = await config.get<string>('path');
    // Backwards compatibility: if it's a relative path with a slash, interpret
    // relative to project root.
    if (!path.isAbsolute(p) && p.includes(path.sep) &&
        vscode.workspace.rootPath !== undefined) {
      p = path.join(vscode.workspace.rootPath, p);
    }

    this._paliPath = p;
  }

  private _paliPath?: string = undefined;

  get paliPath(): string { return this._paliPath as string; }
  set paliPath(p: string) {
    this._pathUpdated = new Promise(resolve => {
      config.update('path', p, vscode.ConfigurationTarget.Global).then(() => {
        this._paliPath = p;
        resolve();
      });
    });
  }
}

// Thin wrapper around `vscode.workspace.getConfiguration('pali')` so the
// install library can read and write settings without depending on the
// extension host directly. Both helpers are async so call sites stay uniform
// even if the underlying API ever becomes asynchronous.

import * as vscode from 'vscode';

const SECTION = 'pali';

/** Read one setting from the `pali` section. */
export async function get<T>(key: string): Promise<T> {
  return vscode.workspace.getConfiguration(SECTION).get<T>(key) as T;
}

/** Write one setting in the `pali` section. */
export async function update(
  key: string,
  value: unknown,
  target: vscode.ConfigurationTarget,
): Promise<void> {
  await vscode.workspace.getConfiguration(SECTION).update(key, value, target);
}

// Runs from the `vscode:uninstall` script in package.json when VS Code
// uninstalls the extension. The hook file this extension writes points at
// `hooks/copilot-hooks.mjs` inside the extension directory, so leaving it
// behind makes every Copilot hook event fail with MODULE_NOT_FOUND once that
// directory is gone. Remove that file — and only that file.

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

/** Directory holding the user-level hook config; tests redirect it. */
function hooksDir(): string {
  return process.env.PALI_HOOKS_DIR || path.join(os.homedir(), '.copilot', 'hooks');
}

/**
 * True when `body` is the hook file this extension writes: hook entries whose
 * commands run `copilot-hooks.mjs`. Anything else at the path belongs to
 * another tool and must survive the uninstall.
 */
function isPaliHookConfig(body: string): boolean {
  try {
    const parsed = JSON.parse(body) as { hooks?: Record<string, unknown> };
    const hooks = parsed?.hooks;
    if (!hooks || typeof hooks !== 'object') return false;
    return Object.values(hooks).some(
      (entries) =>
        Array.isArray(entries) &&
        entries.some((entry) => {
          const commands = entry as { bash?: unknown; powershell?: unknown };
          return [commands?.bash, commands?.powershell].some(
            (value) =>
              typeof value === 'string' && value.includes('copilot-hooks.mjs'),
          );
        }),
    );
  } catch {
    return false;
  }
}

/**
 * Delete the extension's Copilot hook config from `dir`, returning true when a
 * file was removed. A missing file is not an error: the extension never wrote
 * one, or an earlier uninstall already cleaned it up.
 */
export function removeHookConfig(dir: string = hooksDir()): boolean {
  const target = path.join(dir, 'pali.json');
  let body: string;
  try {
    body = fs.readFileSync(target, 'utf8');
  } catch {
    return false;
  }
  if (!isPaliHookConfig(body)) return false;

  try {
    fs.rmSync(target, { force: true });
    return true;
  } catch (error) {
    process.stderr.write(
      `pali: could not remove ${target}: ${(error as Error).message}\n`,
    );
    return false;
  }
}

if (require.main === module) {
  const removed = removeHookConfig();
  process.stderr.write(
    removed
      ? 'pali: removed the Copilot hook config\n'
      : 'pali: no Copilot hook config to remove\n',
  );
}
